//! Local spins and exchange proposals against the Julia GPU oracle (#660, #572).
//!
//! Fixtures: `tests/fixtures/localspin/*.txt`, generated by
//! `gen_localspin_julia.jl` from the committed inputs (provenance in
//! `tests/fixtures/localspin/README.md`). Integers (configurations, acceptance
//! counts) are exact; FP64 values use the bounds stated at each assertion.
use super::tests::{close, sr_backward_error};
use super::*;
use tenferro_ext::raw_exec::raw_exec_counters;

pub(crate) fn input(model: &str) -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/localspin")
        .join(model)
        .join("namelist.def")
}

pub(crate) type Fixture = HashMap<String, Vec<f64>>;

pub(crate) fn parse_fixture(text: &str) -> Fixture {
    let mut tokens = text.split_whitespace();
    let mut fixture = HashMap::new();
    while let Some(name) = tokens.next() {
        let n: usize = tokens.next().unwrap().parse().unwrap();
        let values = (0..n)
            .map(|_| tokens.next().unwrap().parse::<f64>().unwrap())
            .collect();
        fixture.insert(name.to_string(), values);
    }
    fixture
}

pub(crate) fn integers(values: &[f64]) -> Vec<i32> {
    values.iter().map(|&x| x as i32).collect()
}

/// The generator's deterministic tape, `[word][walker][step]`.
pub(crate) fn tape(fixture: &Fixture, walkers: usize, steps: usize) -> Vec<u32> {
    let tape: Vec<u32> = (1..=(5 * walkers * steps) as u64)
        .map(|k| {
            (k.wrapping_mul(0x9e3779b97f4a7c15)
                .wrapping_add(0xbf58476d1ce4e5b9)
                >> 32) as u32
        })
        .collect();
    let head: Vec<u32> = fixture["tape_head"].iter().map(|&x| x as u32).collect();
    assert_eq!(&tape[..head.len()], &head[..], "tape formula");
    let sum = tape.iter().map(|&x| x as u64).sum::<u64>() % (1 << 32);
    assert_eq!(sum as f64, fixture["tape_sum"][0], "tape checksum");
    tape
}

/// Configurations of local-spin sites must stay singly occupied (Julia
/// `validate_initial_walkers`), and every spin sector must be a set of sites.
pub(crate) fn assert_local_spins(model: &Model, cfg: &[i32]) {
    let (ns, ne) = (model.ns, model.ne);
    for walker in cfg.chunks_exact(2 * ne) {
        let mut occupation = vec![0; ns];
        for spin in walker.chunks_exact(ne) {
            let mut seen = vec![false; ns];
            for &site in spin {
                assert!(!seen[site as usize], "doubly occupied spin sector");
                seen[site as usize] = true;
                occupation[site as usize] += 1;
            }
        }
        for (site, &flag) in model.localspins.iter().enumerate() {
            if flag == 1 {
                assert_eq!(occupation[site], 1, "local-spin site {site}");
            }
        }
    }
}

/// [`close`] plus a report of the observed maximum difference.
fn check(name: &str, actual: &[f64], expected: &[f64], atol: f64, rtol: f64) {
    close(name, actual, expected, atol, rtol);
    let worst = actual
        .iter()
        .zip(expected)
        .map(|(a, b)| (a - b).abs())
        .fold(0f64, f64::max);
    println!("  {name}: max abs difference={worst:e}");
}

fn stage_config(steps: usize) -> OptConfig {
    OptConfig {
        nsteps: 1,
        walkers: Some(8),
        warmup: Some(0),
        interval: Some(steps),
        seed: Some(79),
        initial_def: InitialDef::None,
        ..Default::default()
    }
}

fn download<T: Copy + Default>(
    exec: &RawExec<'_, '_>,
    buffer: &DeviceBuffer,
    len: usize,
) -> tenferro_tensor::Result<Vec<T>> {
    let mut out = vec![T::default(); len];
    // SAFETY: every caller passes a length within the buffer's allocation.
    unsafe {
        exec.download(&mut out, exec.ptr(buffer)?)?;
    }
    Ok(out)
}

/// Measure and return (local energies, derivatives) of the current walkers.
fn measure(state: &State, exec: &RawExec<'_, '_>) -> tenferro_tensor::Result<(Vec<f64>, Vec<f64>)> {
    let module = exec.module(SOURCE, KERNELS)?;
    state.observe(exec, &module)?;
    let w = state.resident.sampler.geom.walkers;
    Ok((
        download(exec, &state.buffers.local_energy, w)?,
        download(exec, &state.buffers.derivatives, w * state.model.np)?,
    ))
}

fn assert_opt_flavor(model_name: &str, fixture_text: &str, exchange: f64) {
    let fixture = parse_fixture(fixture_text);
    let model = Model::prepare(&input(model_name), &stage_config(1)).unwrap();
    let steps = 3 * model.ns;
    let config = stage_config(steps);
    let model = Model::prepare(&input(model_name), &config).unwrap();
    assert_eq!(model.exchange, exchange);
    assert_eq!(fixture["exchange"], [exchange]);
    let tape = tape(&fixture, 8, steps);
    let mut backend = CudaEngine::open(cuda_devices().unwrap()[0].id()).unwrap();
    let backend: &mut CudaEngine = &mut backend;
    // Initial parameters come from the shared SFMT init_parameter contract.
    check(
        "parameters",
        &model.parameters,
        &fixture["parameters"],
        1e-14,
        1e-14,
    );
    let mut state = State::prepare(backend, model, &config).unwrap();
    assert!(state.resident.delayed_updates);
    state.initialize(backend).unwrap();
    let initial = state.resident.snapshot(backend).unwrap();
    assert_eq!(
        initial.ele,
        integers(&fixture["initial_cfg"]),
        "exact Julia XORWOW local-spin initialization"
    );
    assert_local_spins(&state.model, &initial.ele);
    // Same bounds as the L128 Opt stage fixture (opt_julia.md): the first
    // floating difference is in the independent factorization.
    check(
        "initial_pf",
        &initial.pf,
        &fixture["initial_pf"],
        1e-12,
        5e-11,
    );
    let (energy, derivatives) =
        with_raw_exec(backend, "localspin.initial", |exec| measure(&state, exec)).unwrap();
    check(
        "initial_energy",
        &energy,
        &fixture["initial_values"],
        1e-10,
        1e-10,
    );
    check(
        "initial_derivatives",
        &derivatives,
        &fixture["initial_derivatives"],
        1e-10,
        1e-10,
    );
    state.resident.advance_with_tape(backend, &tape).unwrap();
    let last = state.resident.snapshot(backend).unwrap();
    assert_eq!(
        last.ele,
        integers(&fixture["final_cfg"]),
        "supplied-tape trajectory"
    );
    assert_eq!(
        state.resident.accepted(backend).unwrap(),
        integers(&fixture["accepted"]),
        "acceptance counts"
    );
    assert_local_spins(&state.model, &last.ele);
    let worst = last
        .pf
        .iter()
        .zip(&fixture["final_pf"])
        .map(|(a, b)| (a - b).abs() / a.abs().max(b.abs()))
        .fold(0f64, f64::max);
    println!("{model_name}: final Pfaffian maximum relative difference={worst:e}");
    // After 3*Nsite proposals the Pfaffians carry the accumulated rank-two /
    // delayed updates and in-kernel refactors of each implementation; the
    // stage bound still applies (observed values are reported above).
    check("final_pf", &last.pf, &fixture["final_pf"], 1e-12, 5e-11);
    let (energy, derivatives, overlaps) = with_raw_exec(backend, "localspin.final", |exec| {
        let (e, d) = measure(&state, exec)?;
        let o = download(exec, &state.buffers.overlaps, e.len())?;
        Ok((e, d, o))
    })
    .unwrap();
    check(
        "final_overlaps",
        &overlaps,
        &fixture["final_overlaps"],
        1e-12,
        5e-11,
    );
    check(
        "final_energy",
        &energy,
        &fixture["final_values"],
        1e-10,
        1e-10,
    );
    check(
        "final_derivatives",
        &derivatives,
        &fixture["final_derivatives"],
        1e-10,
        1e-10,
    );
    let (parameters, update, history) = with_raw_exec(backend, "localspin.update", |exec| {
        let module = exec.module(SOURCE, KERNELS)?;
        state.update(exec, &module, 0)?;
        Ok((
            download(exec, &state.buffers.parameters, state.model.np)?,
            download(exec, &state.buffers.rhs, state.model.np)?,
            download::<f64>(exec, &state.buffers.history, 1)?,
        ))
    })
    .unwrap();
    state.resident.check_status(backend).unwrap();
    check(
        "energy_mean",
        &history,
        &fixture["energy_mean"],
        1e-10,
        1e-10,
    );
    check(
        "parameters_after",
        &parameters,
        &fixture["parameters_after"],
        1e-10,
        1e-10,
    );
    let relative = sr_backward_error(&state.model, &derivatives, &energy, &update);
    assert!(relative < 1e-11, "SR backward error {relative:e}");
    println!("{model_name}: Julia Opt stages passed; SR backward error={relative:e}");
}

#[test]
#[ignore = "requires CUDA; Julia GPU Heisenberg L64 (all exchanges) Opt stages"]
fn resident_opt_matches_julia_heisenberg_exchange() {
    assert_opt_flavor(
        "heisenberg_chain_L64",
        include_str!("../../tests/fixtures/localspin/heisenberg_opt.txt"),
        1.0,
    );
}

#[test]
#[ignore = "requires CUDA; Julia GPU Kondo (local-spin hops, exchanges, delayed queue) Opt stages"]
fn resident_opt_matches_julia_kondo_mixed_moves() {
    assert_opt_flavor(
        "kondo_chain_L64",
        include_str!("../../tests/fixtures/localspin/kondo_opt.txt"),
        0.5,
    );
}

/// Complete 20-step Opt runs repeat exactly within one implementation, after
/// an intervening differently seeded run, with zero explicit transfers and one
/// stream synchronization for the whole warmup/optimization series.
#[test]
#[ignore = "requires CUDA; 20-step local-spin repeatability, transfers and timing"]
fn resident_opt_localspin_repeats_twenty_steps() {
    for (name, walkers) in [("heisenberg_chain_L64", 128), ("kondo_chain_L64", 64)] {
        let config = OptConfig {
            nsteps: 20,
            walkers: Some(walkers),
            warmup: Some(128),
            interval: Some(128),
            seed: Some(79),
            initial_def: InitialDef::None,
            ..Default::default()
        };
        let start = std::time::Instant::now();
        let first = run_gpu_para_opt_from_namelist(input(name), config.clone()).unwrap();
        let first_seconds = start.elapsed().as_secs_f64();
        run_gpu_para_opt_from_namelist(
            input(name),
            OptConfig {
                nsteps: 1,
                walkers: Some(8),
                warmup: Some(0),
                interval: Some(16),
                seed: Some(23),
                ..config.clone()
            },
        )
        .unwrap();
        let start = std::time::Instant::now();
        let second = run_gpu_para_opt_from_namelist(input(name), config.clone()).unwrap();
        let second_seconds = start.elapsed().as_secs_f64();
        // Same implementation, inputs and seed: bitwise repeatability is the
        // contract here, so the bounds are only formatting slack.
        close("energies", &first.energies, &second.energies, 1e-12, 1e-12);
        close(
            "parameters",
            &first.parameters,
            &second.parameters,
            1e-12,
            1e-12,
        );
        assert!(first.energies.iter().all(|e| e.is_finite()));
        let (traffic, run_seconds) = with_runtime(0, |backend| {
            let model = Model::prepare(&input(name), &config)?;
            let mut state = State::prepare(backend, model, &config)?;
            state.initialize(backend)?;
            let before = raw_exec_counters();
            let start = std::time::Instant::now();
            state.run(backend)?;
            let seconds = start.elapsed().as_secs_f64();
            let traffic = raw_exec_counters() - before;
            let result = state.result(backend)?;
            close(
                "resident run",
                &result.energies,
                &first.energies,
                1e-12,
                1e-12,
            );
            Ok((traffic, seconds))
        })
        .unwrap();
        assert_eq!(
            (
                traffic.upload_calls,
                traffic.download_calls,
                traffic.synchronizations
            ),
            (0, 0, 1),
            "{name}: sampling/optimization must stay resident"
        );
        println!(
            "{name}: walkers={walkers} e2e first={first_seconds:.3}s warm={second_seconds:.3}s \
             run={run_seconds:.3}s traffic={traffic:?} energies[0,19]=({:.6},{:.6})",
            first.energies[0], first.energies[19]
        );
    }
}
